"""Task-local inspection: list workspace files and inspect any SQLite databases."""
import os
import sqlite3

print("Current directory:", os.getcwd())
print("\nFiles in workspace:")
for name in sorted(os.listdir(".")):
    marker = " [dir]" if os.path.isdir(name) else ""
    print(f"  {name}{marker}")

print("\nSQLite databases found:")
found = False
for name in sorted(os.listdir(".")):
    if os.path.isfile(name) and name.lower().endswith((".db", ".sqlite", ".sqlite3")):
        found = True
        print(f"\n== {name} ==")
        try:
            with sqlite3.connect(name) as conn:
                tables = [
                    r[0]
                    for r in conn.execute(
                        "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name"
                    )
                ]
                print("Tables:", tables)
                for table in tables:
                    print(f"\n{table} schema:")
                    for row in conn.execute(f"PRAGMA table_info({table})"):
                        print("  ", row)
                    count = conn.execute(f"SELECT COUNT(*) FROM {table}").fetchone()[0]
                    print(f"  row count: {count}")
        except sqlite3.Error as exc:
            print("  could not inspect:", exc)
if not found:
    print("  (none found)")

"""Inspect the workspace for a SQLite database and report its schema.

Task-scoped helper: only reads the local database shape in this folder.
"""
import os
import sqlite3

BASE = os.path.dirname(os.path.abspath(__file__))


def inspect_database(path):
    print("=" * 70)
    print(f"Database: {os.path.basename(path)}  (size: {os.path.getsize(path)} bytes)")
    uri = f"file:{path}?mode=ro"
    conn = sqlite3.connect(uri, uri=True)
    conn.row_factory = sqlite3.Row
    try:
        cur = conn.cursor()
        cur.execute(
            "SELECT name, type, sql FROM sqlite_master "
            "WHERE name NOT LIKE 'sqlite_%' ORDER BY type, name"
        )
        objects = cur.fetchall()
        if not objects:
            print("  (empty database - no user tables)")
            return
        for obj in objects:
            print(f"\n--- {obj['type']}: {obj['name']}")
            if obj["sql"]:
                print(obj["sql"])
            if obj["type"] == "table":
                cur.execute(f'PRAGMA table_info("{obj["name"]}")')
                cols = cur.fetchall()
                print("  columns:")
                for col in cols:
                    print(
                        f"    {col['name']} {col['type']} "
                        f"notnull={col['notnull']} default={col['dflt_value']!r} pk={col['pk']}"
                    )
                try:
                    cur.execute(f'SELECT COUNT(*) AS n FROM "{obj["name"]}"')
                    print(f"  row count: {cur.fetchone()['n']}")
                except sqlite3.Error as exc:
                    print(f"  row count unavailable: {exc}")
    finally:
        conn.close()


def main():
    print("Workspace:", BASE)
    entries = sorted(os.listdir(BASE))
    print("Entries:", entries)

    db_candidates = [
        name for name in entries
        if name.lower().endswith((".db", ".sqlite", ".sqlite3"))
    ]
    if not db_candidates:
        print("NO_DATABASE_FOUND")
        return

    for name in db_candidates:
        try:
            inspect_database(os.path.join(BASE, name))
        except sqlite3.Error as exc:
            print(f"Could not inspect {name}: {exc}")


if __name__ == "__main__":
    main()

